use laddermd_core::{parser, renderer::MarkdownRenderer};
use std::fs;
use std::path::PathBuf;

#[derive(Parser)]
#[command(name = "laddermd", about = "PLCopen XML to Markdown/DSL converter")]
struct Cli {
    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand)]
enum Commands {
    /// Convert PLCopen XML to Markdown
    Convert {
        /// Input XML file
        input: PathBuf,
        /// Output file (defaults to stdout)
        #[arg(short, long)]
        output: Option<PathBuf>,
        /// Disable ASCII diagram output
        #[arg(long)]
        no_diagram: bool,
        /// Disable device table output
        #[arg(long)]
        no_table: bool,
        /// Disable logic expression output
        #[arg(long)]
        no_logic: bool,
    },
    /// Show project information
    Info {
        /// Input XML file
        input: PathBuf,
    },
    /// Validate roundtrip conversion
    Validate {
        /// Input XML file
        input: PathBuf,
    },
}

fn main() -> Result<()> {
    let cli = Cli::parse();

    match cli.command {
        Commands::Convert {
            input,
            output,
            no_diagram,
            no_table,
            no_logic,
        } => {
            let xml = fs::read_to_string(&input)
                .with_context(|| format!("Failed to read {}", input.display()))?;
            let project = parser::parse(&xml)
