            let xml = fs::read_to_string(&input)
                .with_context(|| format!("Failed to read {}", input.display()))?;
            let project = parser::parse(&xml)
                .with_context(|| format!("Failed to parse {}", input.display()))?;

            let total_rungs: usize = project.programs.iter().map(|p| p.rungs.len()).sum();
            println!("Parse OK: {total_rungs} rungs found");

            let mut contacts = 0u32;
            let mut coils = 0u32;
            let mut blocks = 0u32;
            for prog in &project.programs {
                for rung in &prog.rungs {
                    for elem in &rung.elements {
                        match elem {
