16→            }
17→            Ok(Event::Eof) => break,
18→            Err(e) => panic!("{path}: XML parse error at position {}: {e}", reader.error_position()),
19→            _ => {}
20→        }
21→    }
22→    assert_eq!(depth, 0, "{path}: unclosed tags remain (depth={depth})");
