    stack: &mut Vec<LogicNode>,
    all_elements: &mut Vec<RungElement>,
    all_connections: &mut Vec<Connection>,
    output_id: u32,
    output_element: RungElement,
    line: usize,
) -> Result<(), MnemonicParseError> {
    let top = stack.last().ok_or(MnemonicParseError::Syntax {
        line,
        message: "output instruction without prior LD".to_string(),
    })?;

    // Collect all contact IDs that are "leaves" (not connecting to another contact)
    // These are the elements whose output feeds into the coil.
    let all_contact_ids: std::collections::HashSet<u32> = top
        .elements
        .iter()
        .map(|e| match e {
            RungElement::Contact(c) => c.local_id,
            RungElement::Coil(c) => c.local_id,
            RungElement::Block(b) => b.local_id,
        })
        .collect();

    let connected_from: std::collections::HashSet<u32> = top
        .connections
        .iter()
        .map(|c| c.from_id)
        .collect();

    // Leaf elements: those that are not a "from" in any connection (i.e., end of chain)
    let leaf_ids: Vec<u32> = all_contact_ids
        .iter()
        .filter(|id| !connected_from.contains(id))
        .copied()
        .collect();

    // If we have leaves, connect them to the output. Otherwise use last_id.
    if !leaf_ids.is_empty() {
        for &leaf_id in &leaf_ids {
            all_connections.push(Connection {
                from_id: leaf_id,
                to_id: output_id,
            });
        }
    } else if let Some(last_id) = top.last_id {
        all_connections.push(Connection {
            from_id: last_id,
            to_id: output_id,
        });
    }

    // Add all elements from the stack node
    all_elements.extend(top.elements.iter().cloned());
    all_connections.extend(top.connections.iter().cloned());
    all_elements.push(output_element);

    Ok(())
