<body>
    <header>
        <h1>LadderMD</h1>
        <select id="format">
            <option value="xml">PLCopen XML</option>
            <option value="mnemonic">Mitsubishi Mnemonic</option>
        </select>
        <div class="toolbar">
            <button class="primary" onclick="doConvert()">Convert</button>
            <button onclick="doValidate()">Validate</button>
            <button onclick="doXml2mn()">XML → MN</button>
            <button onclick="doMn2xml()">MN → XML</button>
        </div>
    </header>
    <div class="main">
        <div class="panel">
            <div class="panel-header">Input</div>
            <textarea id="input" placeholder="Paste PLCopen XML or Mitsubishi mnemonic here..."></textarea>
        </div>
        <div class="panel">
            <div class="panel-header">Output</div>
            <div id="output"></div>
        </div>
    </div>
    <div class="status" id="status">Ready</div>

    <script>
        // Check if running in Tauri
        const isTauri = window.__TAURI_INTERNALS__ !== undefined;

        async function invoke(cmd, args) {
            if (isTauri) {
                return window.__TAURI_INTERNALS__.invoke(cmd, args);
            }
            // Fallback for browser preview
            return { markdown: 'Run inside Tauri to use conversion features.', project_name: '', rung_count: 0 };
        }

        function setStatus(msg, isError) {
            const el = document.getElementById('status');
            el.innerHTML = isError
                ? `<span class="err">${msg}</span>`
                : `<span class="ok">${msg}</span>`;
        }

        async function doConvert() {
            const input = document.getElementById('input').value;
            const format = document.getElementById('format').value;
            try {
                const cmd = format === 'mnemonic' ? 'convert_mnemonic' : 'convert_xml';
                const arg = format === 'mnemonic' ? { mnemonic: input } : { xml: input };
                const result = await invoke(cmd, arg);
                document.getElementById('output').textContent = result.markdown;
                setStatus(`Converted: ${result.project_name} (${result.rung_count} rungs)`);
            } catch (e) {
                document.getElementById('output').textContent = '';
                setStatus(String(e), true);
            }
        }

        async function doValidate() {
            const xml = document.getElementById('input').value;
            try {
                const result = await invoke('validate_xml', { xml });
                let text = `Parse OK: ${result.total_rungs} rungs\n`;
                text += `Devices: ${result.contacts} contacts, ${result.coils} coils, ${result.blocks} blocks\n`;
                text += result.roundtrip_ok
                    ? 'Roundtrip OK: all rungs logically equivalent'
                    : 'Roundtrip FAILED:\n' + result.errors.map(e => '  - ' + e).join('\n');
                document.getElementById('output').textContent = text;
                setStatus(result.roundtrip_ok ? 'Validation passed' : 'Validation failed', !result.roundtrip_ok);
            } catch (e) {
                setStatus(String(e), true);
            }
        }

        async function doXml2mn() {
            const xml = document.getElementById('input').value;
            try {
                const mn = await invoke('xml_to_mnemonic', { xml });
                document.getElementById('output').textContent = mn;
                setStatus('Converted XML to mnemonic');
            } catch (e) { setStatus(String(e), true); }
        }

        async function doMn2xml() {
            const mnemonic = document.getElementById('input').value;
            try {
                const xml = await invoke('mnemonic_to_xml', { mnemonic });
                document.getElementById('output').textContent = xml;
                setStatus('Converted mnemonic to XML');
            } catch (e) { setStatus(String(e), true); }
        }

        // Load sample on start
        document.getElementById('input').value = `; Self-Hold Circuit
LD  X001
AND X002
OR  Y001
OUT Y001
LD  X003
RST Y001
END`;
        document.getElementById('format').value = 'mnemonic';
    </script>
</body>
